test_input = [[1, 2, 5], [7, 3, 6], [7, 6, 5]]

def solve_arc_puzzle(input_grid):
    h_in, w_in = len(input_grid), len(input_grid[0])
    h_out, w_out = 5, 5
    output = [[0] * w_out for _ in range(h_out)]

    for i in range(h_out):
        for j in range(w_out):
            min_dist = float('inf')
            best_val = input_grid[0][0]

            for r in range(h_in):
                for c in range(w_in):
                    center_x, center_y = r + 1, c + 1
                    dist = ((i - center_x)**2 + (j - center_y)**2)**0.5

                    if dist < min_dist:
                        min_dist = dist
                        best_val = input_grid[r][c]
                    elif dist == min_dist:
                        if i % 2 == 1 or j % 2 == 1:
                            best_val = input_grid[r][c]

            output[i][j] = best_val

    return output

result = solve_arc_puzzle(test_input)
print("Final solution:", result)
